describe('Mark All Notifications as Read', () => {
  beforeEach(() => {
    cy.visit('/notifications');
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          { id: 1, message: 'New message from John', read: false },
          { id: 2, message: 'System update available', read: false },
          { id: 3, message: 'Your order has shipped', read: false }
        ]
      }
    }).as('getNotifications');
    cy.wait('@getNotifications');
  });

  it('should mark all notifications as read when clicking mark all button', () => {
    cy.get('[data-testid="notification-item"]').should('have.length', 3);
    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).should('have.class', 'unread');
    });

    cy.intercept('POST', '/api/notifications/mark-all-read', {
      statusCode: 200,
      body: { success: true, markedCount: 3 }
    }).as('markAllRead');

    cy.get('[data-testid="mark-all-read-btn"]').click();
    cy.wait('@markAllRead');

    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).should('not.have.class', 'unread');
      cy.wrap($notification).should('have.class', 'read');
    });

    cy.get('[data-testid="unread-badge"]').should('not.exist');
  });

  it('should handle edge case when no unread notifications exist', () => {
    cy.intercept('GET', '/api/notifications', {
      statusCode: 200,
      body: {
        notifications: [
          { id: 1, message: 'Old notification', read: true },
          { id: 2, message: 'Another old notification', read: true }
        ]
      }
    }).as('getNotificationsAllRead');

    cy.reload();
    cy.wait('@getNotificationsAllRead');

    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).should('have.class', 'read');
    });

    cy.get('[data-testid="mark-all-read-btn"]').should('be.disabled');
    cy.get('[data-testid="empty-state-message"]').should('contain', 'All notifications are already read');
  });

  it('should handle API error gracefully when marking all as read fails', () => {
    cy.intercept('POST', '/api/notifications/mark-all-read', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('markAllReadError');

    cy.get('[data-testid="mark-all-read-btn"]').click();
    cy.wait('@markAllReadError');

    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to mark notifications as read');

    cy.get('[data-testid="notification-item"]').each(($notification) => {
      cy.wrap($notification).should('have.class', 'unread');
    });
  });

  it('should show loading state while marking all notifications as read', () => {
    cy.intercept('POST', '/api/notifications/mark-all-read', (req) => {
      req.reply((res) => {
        res.delay(1000);
        res.send({
          statusCode: 200,
          body: { success: true, markedCount: 3 }
        });
      });
    }).as('markAllReadDelayed');

    cy.get('[data-testid="mark-all-read-btn"]').click();
    cy.get('[data-testid="mark-all-read-btn"]').should('have.attr', 'disabled');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    cy.wait('@markAllReadDelayed');
    cy.get('[data-testid="mark-all-read-btn"]').should('not.have.attr', 'disabled');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });
});
